"""Care advice for the initial houseplant collection."""

# Each plant's tuple contains moisture-check advice, possible warning signs and general growing conditions, in that order.
INITIAL_CARE = {
    "Money tree": ("Let the top 3–5 cm of compost dry; check the pot feels lighter before watering.", "Yellow soft leaves or a soft trunk can mean wet roots; crispy curling leaves with dry compost can mean thirst.", "Bright indirect light, a draining pot and no standing water; rotate for even growth."),
    "Button fern": ("Check just beneath the surface; water when the top starts to feel slightly dry, not when the whole pot is bone dry.", "Crispy leaflets suggest dryness or low humidity; yellow fronds and sour wet compost suggest excess water.", "Indirect light, moderate humidity and evenly lightly moist, airy compost."),
    "Christmas cactus": ("Let the top 2–3 cm dry, then water and drain; reduce watering in cooler, slower-growing periods.", "Limp segments can mean dry roots or root rot; falling buds may follow temperature or watering changes.", "Bright filtered light, airy compost and cooler autumn nights to encourage flowering."),
    "Fishbone cactus": ("Allow the upper third of the mix to dry, then water thoroughly and drain; don't treat it like a desert cactus.", "Wrinkled stems can mean thirst; soft yellow stems can mean excess water or poor drainage.", "Bright indirect light, airy epiphytic cactus mix and protection from harsh midday sun."),
    "Golden pothos": ("Wait until the upper few centimetres are dry and the pot is lighter.", "Yellowing leaves and soft stems can indicate wet roots; limp leaves with dry compost suggest thirst.", "Bright indirect light, a draining pot and trimming long vines to encourage fuller growth."),
    "Grape ivy": ("Water when the top 2–3 cm dry; avoid leaving the root ball waterlogged.", "Dropping leaves can follow sudden changes, dry soil or soggy roots; inspect undersides for spider mites.", "Bright indirect light, stable temperatures and a well-draining mix."),
    "Jade plant": ("Let the compost dry thoroughly throughout the pot before watering.", "Soft translucent leaves or a mushy stem suggest rot; wrinkled leaves with dry soil suggest thirst.", "Plenty of light, gritty compost and drainage; acclimatise gradually to stronger sun."),
    "Kimberley queen fern": ("Keep compost lightly moist; water as the surface begins to dry, rather than letting it dry completely.", "Brown crispy fronds suggest dry conditions; yellowing and soggy compost suggest poor drainage.", "Bright indirect light, humidity and consistent moisture without standing water."),
    "Lipstick plant": ("Water when the upper few centimetres dry; avoid prolonged sogginess.", "Dropping buds or leaves can follow abrupt changes; soft stems suggest excess moisture.", "Bright indirect light, airy mix, warmth and good drainage to support flowering."),
    "Mother-in-law's tongue": ("Let the compost dry completely before watering; check moisture at depth.", "Mushy leaf bases indicate too much water; wrinkling with bone-dry soil can mean thirst.", "Free-draining gritty mix, drainage holes and moderate to bright indirect light."),
    "Oxalis triangularis": ("During active growth, water when the surface dries slightly; during dormancy, keep much drier.", "Drooping at night is normal; widespread dieback can be natural dormancy, not necessarily a watering problem.", "Bright indirect light; allow a rest if foliage dies back, then resume watering when growth returns."),
    "Parlour palm": ("Let the upper 2–3 cm dry before watering, while avoiding a completely dry root ball for long periods.", "Brown tips may reflect salts, dry air or inconsistent moisture; yellowing can mean overwatering.", "Indirect light, gentle watering and occasional checking for spider mites."),
    "Porcelain plant (Hoya)": ("Allow much of the potting mix to dry before watering; check pot weight and leaf firmness.", "Yellow soft leaves or blackened roots suggest excess water; wrinkled leaves may indicate thirst or damaged roots.", "Bright indirect light, a chunky airy mix and drainage; avoid repotting too frequently."),
    "Rattlesnake plant": ("Water when the surface just begins to dry; keep evenly lightly moist, never saturated.", "Crispy edges may reflect low humidity or mineral-heavy water; yellow leaves and wet soil can mean root stress.", "Gentle indirect light, stable warmth, humidity and rainwater or other low-mineral water where possible."),
    "Silver inch plant": ("Let the upper 2–3 cm dry before watering; don't keep stems constantly wet.", "Leggy growth suggests low light; soft stems can mean excess water; dry crispy leaves may indicate thirst.", "Bright indirect light, pinch stems to keep bushy and avoid water sitting on foliage."),
    "String of hearts": ("Let the mix dry almost completely and check whether leaves feel thinner or less firm.", "Yellow mushy leaves suggest excess water; shrivelling with dry compost can indicate thirst.", "Very bright indirect light, a small draining pot and an airy mix."),
    "Cape sundew": ("Keep the pot standing in a shallow tray of rainwater, distilled or reverse-osmosis water; its medium should remain consistently wet.", "Loss of sticky dew can indicate insufficient light or stress; brown growth may result from mineral-rich tap water or drying out.", "Strong light, nutrient-poor carnivorous-plant compost and mineral-free water; never fertilise the soil."),
}

# Names used when seeding a new collection for the first time; existing collections are not reset by this list.
INITIAL_PLANTS = ["Money tree","Button fern","Christmas cactus","Fishbone cactus","Golden pothos","Grape ivy","Jade plant","Kimberley queen fern","Lipstick plant","Mother-in-law's tongue","Oxalis triangularis","Parlour palm","Porcelain plant (Hoya)","Rattlesnake plant","Silver inch plant","String of hearts","Cape sundew"]
